async function collectFunctionFiles({ functionPath, functionName }) {
	const normalizedFunctionPath = path.resolve(functionPath);
	const stats = await fsPromises.stat(normalizedFunctionPath);
	let functionDirectory = null;
	if (stats.isDirectory()) functionDirectory = normalizedFunctionPath;
	if (!functionDirectory) throw new CaideError(`Unable to locate directory for Supabase function ${functionName}`, CaideErrorKind.NotFound);
	const indexPath = path.join(functionDirectory, "index.ts");
	try {
		await fsPromises.access(indexPath);
	} catch {
		throw new CaideError(`Supabase function ${functionName} is missing an index.ts entrypoint`, CaideErrorKind.Validation);
	}
	const statEntries = await listFilesWithStats(functionDirectory, functionName);
	const signature = buildSignature(statEntries);
	return {
		files: await loadZipEntries(statEntries),
		signature,
		entrypointPath: path.posix.join(functionName, toPosixPath(path.relative(functionDirectory, indexPath))),
		cacheKey: functionDirectory
	};
}
async function getSharedFiles(appPath) {
	const sharedDirectory = path.join(appPath, "supabase", "functions", "_shared");
	try {
		if (!(await fsPromises.stat(sharedDirectory)).isDirectory()) return {
			signature: "",
			files: []
		};
	} catch (error) {
		if (error && error.code === "ENOENT") return {
			signature: "",
			files: []
		};
		throw error;
	}
	const statEntries = await listFilesWithStats(sharedDirectory, "_shared");
	const signature = buildSignature(statEntries);
	const cached = sharedFilesCache.get(sharedDirectory);
	if (cached && cached.signature === signature) return cached;
	const result = {
		signature,
		files: await loadZipEntries(statEntries)
	};
	sharedFilesCache.set(sharedDirectory, result);
	return result;
}
async function listFilesWithStats(directory, prefix) {
	const dirents = await fsPromises.readdir(directory, { withFileTypes: true });
	dirents.sort((a, b) => a.name.localeCompare(b.name));
	const entries = [];
	for (const dirent of dirents) {
		const absolutePath = path.join(directory, dirent.name);
		const relativePath = path.posix.join(prefix, dirent.name);
		if (dirent.isDirectory()) {
			const nestedEntries = await listFilesWithStats(absolutePath, relativePath);
			entries.push(...nestedEntries);
		} else if (dirent.isFile() || dirent.isSymbolicLink()) {
			const stat = await fsPromises.stat(absolutePath);
			entries.push({
				absolutePath,
				relativePath,
				mtimeMs: stat.mtimeMs,
				size: stat.size
			});
		}
	}
	return entries;
}
function buildSignature(entries) {
	return entries.map((entry) => `${entry.relativePath}:${entry.mtimeMs.toString(16)}:${entry.size.toString(16)}`).sort().join("|");
}
async function loadZipEntries(entries) {
	const files = [];
	for (const entry of entries) {
		const content = await fsPromises.readFile(entry.absolutePath);
		files.push({
			relativePath: toPosixPath(entry.relativePath),
			content,
			date: new Date(entry.mtimeMs)
		});
	}
	return files;
}
function toPosixPath(filePath) {
	return filePath.split(path.sep).join(path.posix.sep);
}
function guessMimeType(filePath) {
	if (filePath.endsWith(".json")) return "application/json";
	if (filePath.endsWith(".ts")) return "application/typescript";
	if (filePath.endsWith(".mjs")) return "application/javascript";
	if (filePath.endsWith(".js")) return "application/javascript";
	if (filePath.endsWith(".wasm")) return "application/wasm";
	if (filePath.endsWith(".map")) return "application/json";
	return "application/octet-stream";
}
async function createResponseError(response, action) {
	const errorBody = await safeParseErrorResponseBody(response);
	return new SupabaseManagementAPIError(`Failed to ${action}: ${response.statusText} (${response.status})${errorBody ? `: ${errorBody.message}` : ""}`, response);
}
async function safeParseErrorResponseBody(response) {
	try {
		const body = await response.json();
		if (typeof body === "object" && body !== null && "message" in body && typeof body.message === "string") return { message: body.message };
	} catch {
		return;
	}
}

